import{_ as a,H as r,f as o,i}from"./chunks/framework.Cvt1eIE0.js";const c=JSON.parse('{"title":"12-메모리","description":"","frontmatter":{},"headers":[],"relativePath":"13-memory.md","filePath":"13-memory.md","lastUpdated":1778828590000}'),l={name:"13-memory.md"};function s(t,e,n,m,h,d){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="_12-메모리" tabindex="-1">12-메모리 <a class="header-anchor" href="#_12-메모리" aria-label="Permalink to &quot;12-메모리&quot;">​</a></h1><p>Grok Build는 기본적으로 <strong>세션 단위</strong>로 동작합니다.<br> 즉, 새로운 세션을 시작하면 이전 세션에서 했던 대화나 결정 사항을 전혀 기억하지 못합니다.</p><p>하지만 프로젝트를 오랫동안 작업하다 보면, “이전에 설명했던 규칙”, “지난번에 해결했던 버그 패턴”, “팀의 아키텍처 결정” 등을 매번 다시 설명하는 것이 매우 비효율적입니다.</p><p>이런 문제를 해결하기 위해 Grok Build가 제공하는 기능이 바로 <strong>Memory</strong>입니다.</p><hr><h2 id="memory란-무엇인가" tabindex="-1">Memory란 무엇인가? <a class="header-anchor" href="#memory란-무엇인가" aria-label="Permalink to &quot;Memory란 무엇인가?&quot;">​</a></h2><h3 id="memory의-개념" tabindex="-1">Memory의 개념 <a class="header-anchor" href="#memory의-개념" aria-label="Permalink to &quot;Memory의 개념&quot;">​</a></h3><p><strong>Memory</strong>는 Grok이 여러 세션에 걸쳐 <strong>중요한 정보</strong>를 기억하고, 필요할 때 자동으로 불러올 수 있게 해주는 기능입니다.</p><p>Memory에 저장되는 정보의 예시:</p><ul><li>프로젝트의 코딩 컨벤션</li><li>자주 사용되는 디버깅 방법</li><li>아키텍처 결정 사항</li><li>특정 파일이나 함수에 대한 설명</li><li>팀의 개발 규칙</li><li>이전에 해결했던 문제와 그 해결책</li></ul><p>Memory가 활성화되어 있으면, Grok은 사용자가 질문할 때마다 자동으로 관련된 Memory를 검색해서 참고합니다.</p><h3 id="memory-vs-agents-md-vs-skill" tabindex="-1">Memory vs AGENTS.md vs Skill <a class="header-anchor" href="#memory-vs-agents-md-vs-skill" aria-label="Permalink to &quot;Memory vs AGENTS.md vs Skill&quot;">​</a></h3><table tabindex="0"><thead><tr><th>기능</th><th>지속 범위</th><th>활성화 방식</th><th>목적</th></tr></thead><tbody><tr><td><strong>AGENTS.md</strong></td><td>프로젝트 전체</td><td>항상 적용</td><td>프로젝트의 큰 방향과 규칙</td></tr><tr><td><strong>Skill</strong></td><td>특정 작업/상황</td><td>필요할 때 호출</td><td>반복되는 작업 절차</td></tr><tr><td><strong>Memory</strong></td><td>여러 세션에 걸쳐</td><td>자동 검색</td><td>장기 기억 (사실, 결정, 패턴)</td></tr></tbody></table><p>Memory는 <strong>“한 번 알려주면 계속 기억하는”</strong> 가장 편리한 방법입니다.</p><hr><h2 id="memory-활성화-방법" tabindex="-1">Memory 활성화 방법 <a class="header-anchor" href="#memory-활성화-방법" aria-label="Permalink to &quot;Memory 활성화 방법&quot;">​</a></h2><p>Memory는 기본적으로 <strong>비활성화</strong>되어 있습니다. (실험적 기능)</p><h3 id="_1-cli-플래그로-활성화-임시" tabindex="-1">1. CLI 플래그로 활성화 (임시) <a class="header-anchor" href="#_1-cli-플래그로-활성화-임시" aria-label="Permalink to &quot;1. CLI 플래그로 활성화 (임시)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --experimental-memory</span></span></code></pre></div><h3 id="_2-환경-변수로-활성화-권장" tabindex="-1">2. 환경 변수로 활성화 (권장) <a class="header-anchor" href="#_2-환경-변수로-활성화-권장" aria-label="Permalink to &quot;2. 환경 변수로 활성화 (권장)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GROK_MEMORY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span></span></code></pre></div><p>이 방법은 터미널 세션 동안 Memory를 활성화합니다.</p><h3 id="_3-config-toml에서-영구-활성화-가장-추천" tabindex="-1">3. config.toml에서 영구 활성화 (가장 추천) <a class="header-anchor" href="#_3-config-toml에서-영구-활성화-가장-추천" aria-label="Permalink to &quot;3. config.toml에서 영구 활성화 (가장 추천)&quot;">​</a></h3><p><code>~/.grok/config.toml</code>에 아래 내용을 추가하세요:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">memory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">max_memories = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 저장할 수 있는 최대 Memory 개수</span></span></code></pre></div><h3 id="memory-강제-비활성화" tabindex="-1">Memory 강제 비활성화 <a class="header-anchor" href="#memory-강제-비활성화" aria-label="Permalink to &quot;Memory 강제 비활성화&quot;">​</a></h3><p>Memory를 사용하고 싶지 않을 때는:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-memory</span></span></code></pre></div><hr><h2 id="memory가-어떻게-동작하는가" tabindex="-1">Memory가 어떻게 동작하는가? <a class="header-anchor" href="#memory가-어떻게-동작하는가" aria-label="Permalink to &quot;Memory가 어떻게 동작하는가?&quot;">​</a></h2><h3 id="memory-저장-과정" tabindex="-1">Memory 저장 과정 <a class="header-anchor" href="#memory-저장-과정" aria-label="Permalink to &quot;Memory 저장 과정&quot;">​</a></h3><p>Grok이 대화 중에 중요한 정보를 발견하면, 자동으로 Memory에 저장합니다.</p><p>예를 들어 사용자가 다음과 같이 말하면:</p><blockquote><p>“이 프로젝트에서는 커밋 메시지를 Conventional Commits 형식으로 작성해.”</p></blockquote><p>Grok은 이 정보를 Memory에 저장합니다.</p><h3 id="memory-검색-과정" tabindex="-1">Memory 검색 과정 <a class="header-anchor" href="#memory-검색-과정" aria-label="Permalink to &quot;Memory 검색 과정&quot;">​</a></h3><p>이후에 사용자가 다음과 같이 물으면:</p><blockquote><p>“커밋 메시지 어떻게 작성해?”</p></blockquote><p>Grok은 자동으로 Memory를 검색해서 이전에 저장된 “Conventional Commits” 규칙을 찾아서 참고합니다.</p><h3 id="memory의-특징" tabindex="-1">Memory의 특징 <a class="header-anchor" href="#memory의-특징" aria-label="Permalink to &quot;Memory의 특징&quot;">​</a></h3><ul><li><strong>자동 검색</strong>: 사용자가 직접 Memory를 요청하지 않아도, Grok이 필요하다고 판단하면 자동으로 불러옵니다.</li><li><strong>검색 가능</strong>: <code>/memory search &lt;키워드&gt;</code> 명령어로 직접 Memory를 검색할 수 있습니다.</li><li><strong>관리 가능</strong>: <code>/memory list</code>, <code>/memory delete</code> 등으로 Memory를 직접 관리할 수 있습니다.</li></ul><hr><h2 id="간단한-사용-예시" tabindex="-1">간단한 사용 예시 <a class="header-anchor" href="#간단한-사용-예시" aria-label="Permalink to &quot;간단한 사용 예시&quot;">​</a></h2><h3 id="예시-1-프로젝트-컨벤션-기억시키기" tabindex="-1">예시 1: 프로젝트 컨벤션 기억시키기 <a class="header-anchor" href="#예시-1-프로젝트-컨벤션-기억시키기" aria-label="Permalink to &quot;예시 1: 프로젝트 컨벤션 기억시키기&quot;">​</a></h3><p><strong>첫 번째 세션</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>이 프로젝트는 TypeScript를 사용하고, any 타입은 최대한 피해. </span></span>\n<span class="line"><span>컴포넌트는 함수형으로만 작성하고, 상태 관리는 Zustand를 사용해.</span></span></code></pre></div><p>Grok이 이 정보를 Memory에 저장합니다.</p><p><strong>다음 세션</strong> (새로운 세션):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UserProfile 컴포넌트를 만들어줘.</span></span></code></pre></div><p>Grok은 자동으로 Memory에서 “함수형 컴포넌트 + TypeScript + Zustand” 규칙을 찾아서 적용합니다.</p><h3 id="예시-2-디버깅-패턴-기억시키기" tabindex="-1">예시 2: 디버깅 패턴 기억시키기 <a class="header-anchor" href="#예시-2-디버깅-패턴-기억시키기" aria-label="Permalink to &quot;예시 2: 디버깅 패턴 기억시키기&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>지난번에 이 에러는 prisma client가 초기화되지 않아서 발생했었어. </span></span>\n<span class="line"><span>이런 경우에는 npx prisma generate를 먼저 실행하는 게 좋아.</span></span></code></pre></div><p>이후에 비슷한 에러가 발생하면 Grok이 자동으로 이 해결 방법을 제안합니다.</p><hr><p>지금까지 다음 내용을 다루었습니다:</p><ul><li>Memory의 개념과 필요성</li><li>Memory 활성화 방법 (CLI, 환경변수, config.toml)</li><li>Memory가 어떻게 동작하는지</li><li>간단한 사용 예시</li></ul><hr><h2 id="memory-관리-명령어" tabindex="-1">Memory 관리 명령어 <a class="header-anchor" href="#memory-관리-명령어" aria-label="Permalink to &quot;Memory 관리 명령어&quot;">​</a></h2><p>Memory는 <code>/memory</code> 명령어를 통해 직접 관리할 수 있습니다.</p><h3 id="memory-list" tabindex="-1"><code>/memory list</code> <a class="header-anchor" href="#memory-list" aria-label="Permalink to &quot;`/memory list`&quot;">​</a></h3><p>현재 저장된 Memory 목록을 보여줍니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/memory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><ul><li>저장된 Memory의 제목과 간단한 내용, 저장 시점을 확인할 수 있습니다.</li></ul><h3 id="memory-search-키워드" tabindex="-1"><code>/memory search &lt;키워드&gt;</code> <a class="header-anchor" href="#memory-search-키워드" aria-label="Permalink to &quot;`/memory search &lt;키워드&gt;`&quot;">​</a></h3><p>키워드로 Memory를 검색합니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/memory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prisma</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/memory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> authentication</span></span></code></pre></div><ul><li>Grok이 자동으로 검색하지 못한 Memory를 직접 찾아보고 싶을 때 유용합니다.</li></ul><h3 id="memory-delete-id" tabindex="-1"><code>/memory delete &lt;id&gt;</code> <a class="header-anchor" href="#memory-delete-id" aria-label="Permalink to &quot;`/memory delete &lt;id&gt;`&quot;">​</a></h3><p>특정 Memory를 삭제합니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/memory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 123</span></span></code></pre></div><h3 id="memory-clear" tabindex="-1"><code>/memory clear</code> <a class="header-anchor" href="#memory-clear" aria-label="Permalink to &quot;`/memory clear`&quot;">​</a></h3><p>모든 Memory를 삭제합니다.</p><p><strong>주의</strong>: 이 명령어는 되돌릴 수 없으니 신중하게 사용하세요.</p><hr><h2 id="memory-저장-전략-무엇을-저장하면-좋은가" tabindex="-1">Memory 저장 전략 (무엇을 저장하면 좋은가) <a class="header-anchor" href="#memory-저장-전략-무엇을-저장하면-좋은가" aria-label="Permalink to &quot;Memory 저장 전략 (무엇을 저장하면 좋은가)&quot;">​</a></h2><p>Memory는 자동으로 저장되기도 하지만, 사용자가 직접 중요한 정보를 Memory에 저장하는 것도 가능합니다.</p><h3 id="저장하면-좋은-정보" tabindex="-1">저장하면 좋은 정보 <a class="header-anchor" href="#저장하면-좋은-정보" aria-label="Permalink to &quot;저장하면 좋은 정보&quot;">​</a></h3><p><strong>1. 프로젝트 컨벤션</strong></p><ul><li>“이 프로젝트는 Prettier + ESLint를 사용하고, airbnb 스타일을 따릅니다.”</li><li>“함수형 컴포넌트만 사용하고, 클래스 컴포넌트는 금지합니다.”</li></ul><p><strong>2. 디버깅 패턴</strong></p><ul><li>“Prisma 관련 에러가 발생하면 npx prisma generate를 먼저 실행해보기.”</li><li>“TypeScript any 에러는 as unknown as Type으로 우회하는 경우가 많음.”</li></ul><p><strong>3. 아키텍처 결정</strong></p><ul><li>“이 프로젝트의 상태 관리는 Zustand를 사용하고, store는 src/store/에 위치합니다.”</li><li>“API 호출은 모두 src/api/ 폴더에 모아두었습니다.”</li></ul><p><strong>4. 팀 규칙</strong></p><ul><li>“커밋 메시지는 Conventional Commits 형식을 따릅니다.”</li><li>“PR을 올릴 때는 반드시 테스트 결과를 포함해야 합니다.”</li></ul><p><strong>5. 자주 묻는 질문에 대한 답변</strong></p><ul><li>“이 에러의 원인은 보통 .env 파일이 로드되지 않아서입니다.”</li></ul><h3 id="저장하면-안-좋은-정보" tabindex="-1">저장하면 안 좋은 정보 <a class="header-anchor" href="#저장하면-안-좋은-정보" aria-label="Permalink to &quot;저장하면 안 좋은 정보&quot;">​</a></h3><ul><li>너무 자주 바뀌는 정보 (예: 현재 진행 중인 작업 내용)</li><li>한 번만 사용하는 임시 정보</li><li>개인적인 메모 (Memory는 프로젝트 단위로 공유될 수 있음)</li></ul><hr><h2 id="memory와-agents-md-skill의-함께-쓰는-방법" tabindex="-1">Memory와 AGENTS.md, Skill의 함께 쓰는 방법 <a class="header-anchor" href="#memory와-agents-md-skill의-함께-쓰는-방법" aria-label="Permalink to &quot;Memory와 AGENTS.md, Skill의 함께 쓰는 방법&quot;">​</a></h2><h3 id="agents-md-memory" tabindex="-1">AGENTS.md + Memory <a class="header-anchor" href="#agents-md-memory" aria-label="Permalink to &quot;AGENTS.md + Memory&quot;">​</a></h3><ul><li><strong>AGENTS.md</strong>: 프로젝트의 <strong>큰 방향</strong>과 <strong>영구적인 규칙</strong>을 담당</li><li><strong>Memory</strong>: 프로젝트를 진행하면서 <strong>발견한 사실이나 패턴</strong>을 저장</li></ul><p><strong>예시</strong>:</p><ul><li>AGENTS.md: “이 프로젝트는 TypeScript를 사용합니다.”</li><li>Memory: “이전 세션에서 UserService.ts의 getUserById 함수가 null을 반환할 수 있다는 것을 발견함.”</li></ul><h3 id="skill-memory" tabindex="-1">Skill + Memory <a class="header-anchor" href="#skill-memory" aria-label="Permalink to &quot;Skill + Memory&quot;">​</a></h3><ul><li><strong>Skill</strong>: 특정 작업을 <strong>어떻게 수행할지</strong>에 대한 절차를 정의</li><li><strong>Memory</strong>: 그 작업을 수행하면서 <strong>발견한 팁이나 주의사항</strong>을 저장</li></ul><p><strong>예시</strong>:</p><ul><li>Skill: <code>unit-test-generation</code> (테스트 작성 절차)</li><li>Memory: “이 프로젝트에서는 MSW를 사용한 API 모킹을 선호합니다.”</li></ul><p>이렇게 세 가지를 잘 조합하면, Grok이 프로젝트를 점점 더 잘 이해하고 도와줄 수 있습니다.</p><hr><h2 id="privacy와-보안-고려사항" tabindex="-1">Privacy와 보안 고려사항 <a class="header-anchor" href="#privacy와-보안-고려사항" aria-label="Permalink to &quot;Privacy와 보안 고려사항&quot;">​</a></h2><h3 id="memory에-저장되는-정보" tabindex="-1">Memory에 저장되는 정보 <a class="header-anchor" href="#memory에-저장되는-정보" aria-label="Permalink to &quot;Memory에 저장되는 정보&quot;">​</a></h3><p>Memory는 사용자가 명시적으로 지우지 않는 한, 계속 저장됩니다.</p><p>따라서 다음 정보는 Memory에 저장되지 않도록 주의해야 합니다:</p><ul><li>API 키, 비밀번호, 토큰 등 민감한 정보</li><li>고객 데이터나 개인정보</li><li>회사 내부의 비밀 프로젝트 내용</li></ul><h3 id="memory-삭제-방법" tabindex="-1">Memory 삭제 방법 <a class="header-anchor" href="#memory-삭제-방법" aria-label="Permalink to &quot;Memory 삭제 방법&quot;">​</a></h3><ul><li><code>/memory delete &lt;id&gt;</code>: 특정 Memory 삭제</li><li><code>/memory clear</code>: 모든 Memory 삭제</li></ul><p>중요한 프로젝트를 다룰 때는, 작업이 끝난 후 <code>/memory clear</code>를 하는 습관을 들이는 것도 좋습니다.</p><h3 id="memory는-어디에-저장되나" tabindex="-1">Memory는 어디에 저장되나? <a class="header-anchor" href="#memory는-어디에-저장되나" aria-label="Permalink to &quot;Memory는 어디에 저장되나?&quot;">​</a></h3><p>Memory는 <code>~/.grok/memory/</code> 폴더에 저장됩니다.</p><ul><li>Global Memory: 모든 프로젝트에서 공유</li><li>Project Memory: 특정 프로젝트에만 적용 (추후 지원 예정)</li></ul><p>현재는 대부분 Global Memory로 동작합니다.</p><hr><p>지금까지 Memory 관리 명령어, 저장 전략, 다른 확장 기능과의 연동, 그리고 보안 고려사항을 다루었습니다.</p><hr><h2 id="memory-활성화-시-grok의-동작-변화" tabindex="-1">Memory 활성화 시 Grok의 동작 변화 <a class="header-anchor" href="#memory-활성화-시-grok의-동작-변화" aria-label="Permalink to &quot;Memory 활성화 시 Grok의 동작 변화&quot;">​</a></h2><p>Memory를 활성화하면 Grok의 행동에 다음과 같은 변화가 생깁니다.</p><h3 id="_1-자동으로-관련-memory-검색" tabindex="-1">1. 자동으로 관련 Memory 검색 <a class="header-anchor" href="#_1-자동으로-관련-memory-검색" aria-label="Permalink to &quot;1. 자동으로 관련 Memory 검색&quot;">​</a></h3><p>사용자가 질문을 하면, Grok이 자동으로 Memory를 검색해서 관련된 정보를 찾아봅니다.</p><p>예:</p><ul><li>“이전에 설명했던 인증 방식이 뭐였지?”라고 물으면, Memory에 저장된 인증 관련 내용을 자동으로 불러와서 답변합니다.</li></ul><h3 id="_2-반복-질문-감소" tabindex="-1">2. 반복 질문 감소 <a class="header-anchor" href="#_2-반복-질문-감소" aria-label="Permalink to &quot;2. 반복 질문 감소&quot;">​</a></h3><p>같은 질문을 여러 번 하지 않아도 됩니다.</p><ul><li>“이 프로젝트의 상태 관리 방식이 뭐였더라?”</li><li>“지난번에 이 버그는 어떻게 해결했었지?”</li></ul><p>이런 질문들이 줄어듭니다.</p><h3 id="_3-프로젝트-이해도-향상" tabindex="-1">3. 프로젝트 이해도 향상 <a class="header-anchor" href="#_3-프로젝트-이해도-향상" aria-label="Permalink to &quot;3. 프로젝트 이해도 향상&quot;">​</a></h3><p>Grok이 프로젝트를 점점 더 잘 이해하게 됩니다.</p><ul><li>초기에는 “이 프로젝트가 뭘 하는 건가요?”라고 물을 수 있지만,</li><li>Memory가 쌓일수록 “이 프로젝트의 결제 모듈은 어떻게 되어 있나요?”처럼 구체적인 질문을 할 수 있게 됩니다.</li></ul><h3 id="_4-컨텍스트-효율성-증가" tabindex="-1">4. 컨텍스트 효율성 증가 <a class="header-anchor" href="#_4-컨텍스트-효율성-증가" aria-label="Permalink to &quot;4. 컨텍스트 효율성 증가&quot;">​</a></h3><p>Memory가 중요한 정보를 대신 기억해주기 때문에, 매 세션마다 긴 설명을 반복하지 않아도 됩니다. 결과적으로 컨텍스트 창을 더 효율적으로 사용할 수 있습니다.</p><hr><h2 id="memory-사용-시-주의할-점과-한계" tabindex="-1">Memory 사용 시 주의할 점과 한계 <a class="header-anchor" href="#memory-사용-시-주의할-점과-한계" aria-label="Permalink to &quot;Memory 사용 시 주의할 점과 한계&quot;">​</a></h2><h3 id="memory의-한계" tabindex="-1">Memory의 한계 <a class="header-anchor" href="#memory의-한계" aria-label="Permalink to &quot;Memory의 한계&quot;">​</a></h3><p><strong>1. 실험적 기능</strong></p><ul><li>Memory는 아직 실험적(experimental) 기능입니다.</li><li>동작이 완벽하지 않을 수 있고, 예기치 않은 문제가 발생할 수 있습니다.</li></ul><p><strong>2. 정확성 보장 없음</strong></p><ul><li>Grok이 Memory를 잘못 해석하거나, 오래된 정보를 그대로 사용할 수 있습니다.</li><li>중요한 정보는 Memory에만 의존하지 말고, AGENTS.md나 문서에도 함께 기록하는 것이 좋습니다.</li></ul><p><strong>3. 컨텍스트 제한</strong></p><ul><li>Memory는 무한대로 저장되지 않습니다. (설정에서 <code>max_memories</code>로 제한 가능)</li><li>너무 많은 Memory가 쌓이면 검색 효율이 떨어질 수 있습니다.</li></ul><p><strong>4. 프로젝트 간 격리 부족 (현재)</strong></p><ul><li>현재 Memory는 대부분 Global Memory로 동작합니다.</li><li>여러 프로젝트를 동시에 진행할 경우, Memory가 섞일 수 있습니다.</li><li>(추후 프로젝트별 Memory 격리 기능이 추가될 예정)</li></ul><hr><h2 id="memory-관련-best-practices" tabindex="-1">Memory 관련 Best Practices <a class="header-anchor" href="#memory-관련-best-practices" aria-label="Permalink to &quot;Memory 관련 Best Practices&quot;">​</a></h2><h3 id="_1-memory는-보조-기억장치-로-활용하라" tabindex="-1">1. Memory는 “보조 기억장치”로 활용하라 <a class="header-anchor" href="#_1-memory는-보조-기억장치-로-활용하라" aria-label="Permalink to &quot;1. Memory는 “보조 기억장치”로 활용하라&quot;">​</a></h3><p>Memory는 완벽한 기억을 보장하지 않습니다.<br> 중요한 결정이나 규칙은 <strong>AGENTS.md</strong>에도 함께 기록하는 것을 추천합니다.</p><h3 id="_2-memory가-자동으로-저장하게-두되-주기적으로-정리하라" tabindex="-1">2. Memory가 자동으로 저장하게 두되, 주기적으로 정리하라 <a class="header-anchor" href="#_2-memory가-자동으로-저장하게-두되-주기적으로-정리하라" aria-label="Permalink to &quot;2. Memory가 자동으로 저장하게 두되, 주기적으로 정리하라&quot;">​</a></h3><ul><li><code>/memory list</code>로 주기적으로 저장된 Memory를 확인하세요.</li><li>불필요하거나 잘못 저장된 Memory는 <code>/memory delete</code>로 정리하는 습관을 들이세요.</li></ul><h3 id="_3-중요한-정보는-명확하게-전달하라" tabindex="-1">3. 중요한 정보는 명확하게 전달하라 <a class="header-anchor" href="#_3-중요한-정보는-명확하게-전달하라" aria-label="Permalink to &quot;3. 중요한 정보는 명확하게 전달하라&quot;">​</a></h3><p>Memory에 저장하고 싶은 내용이 있다면, 명확하고 구체적으로 말하는 것이 좋습니다.</p><p><strong>좋은 예</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>이 프로젝트에서는 인증 관련 로직은 src/auth/에 모아두고, JWT를 사용합니다.</span></span></code></pre></div><p><strong>나쁜 예</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>인증은 적절히 해.</span></span></code></pre></div><h3 id="_4-memory-agents-md-skill-조합을-적극-활용하라" tabindex="-1">4. Memory + AGENTS.md + Skill 조합을 적극 활용하라 <a class="header-anchor" href="#_4-memory-agents-md-skill-조합을-적극-활용하라" aria-label="Permalink to &quot;4. Memory + AGENTS.md + Skill 조합을 적극 활용하라&quot;">​</a></h3><ul><li><strong>AGENTS.md</strong>: 프로젝트의 큰 방향</li><li><strong>Skill</strong>: 반복 작업의 절차</li><li><strong>Memory</strong>: 발견한 사실과 패턴</li></ul><p>이 세 가지를 잘 조합하면 Grok이 프로젝트를 매우 잘 이해하고 도와줄 수 있습니다.</p><h3 id="_5-중요한-프로젝트에서는-memory-사용을-신중하게" tabindex="-1">5. 중요한 프로젝트에서는 Memory 사용을 신중하게 <a class="header-anchor" href="#_5-중요한-프로젝트에서는-memory-사용을-신중하게" aria-label="Permalink to &quot;5. 중요한 프로젝트에서는 Memory 사용을 신중하게&quot;">​</a></h3><p>고객 데이터, 보안이 중요한 프로젝트, 또는 내부 비밀 프로젝트에서는 Memory 사용을 최소화하거나 사용하지 않는 것을 고려하세요.</p><hr><hr><h2 id="배경-지식-이-기능이-왜-이렇게-동작하는가" tabindex="-1">배경 지식: 이 기능이 왜 이렇게 동작하는가 <a class="header-anchor" href="#배경-지식-이-기능이-왜-이렇게-동작하는가" aria-label="Permalink to &quot;배경 지식: 이 기능이 왜 이렇게 동작하는가&quot;">​</a></h2><blockquote><p><strong>참고</strong>: 이 섹션은 Grok 공식 문서에 명시된 설계 의도를 그대로 설명한 것이 아닙니다.<br> 실제 동작 방식과 관찰, 그리고 논리적 해석을 바탕으로 작성한 <strong>참고용 설명</strong>입니다.<br> xAI에서 공식적으로 발표한 설계 철학이 아니라는 점을 참고해 주세요.</p></blockquote><p>Memory 시스템이 현재와 같은 형태로 제공되는 배경과 특징을 정리했습니다.</p><h3 id="_1-왜-memory가-세션과-독립적으로-동작하나" tabindex="-1">1. 왜 Memory가 세션과 독립적으로 동작하나? <a class="header-anchor" href="#_1-왜-memory가-세션과-독립적으로-동작하나" aria-label="Permalink to &quot;1. 왜 Memory가 세션과 독립적으로 동작하나?&quot;">​</a></h3><p>Grok Build는 기본적으로 <strong>세션 단위</strong>로 동작합니다.<br> 하지만 프로젝트를 오래 하다 보면, “이전에 설명했던 규칙”이나 “해결했던 버그 패턴”을 매번 다시 알려주는 것이 매우 비효율적입니다.</p><p>그래서 Memory는 <strong>세션과 별개로</strong> 중요한 정보를 저장하고, 필요할 때 자동으로 불러오는 방식으로 동작합니다.<br> 이렇게 하면 사용자가 “이건 이전에 말했던 내용이야”라고 일일이 알려주지 않아도 Grok이 스스로 기억할 수 있습니다.</p><h3 id="_2-왜-현재는-global-memory로-동작하나" tabindex="-1">2. 왜 현재는 Global Memory로 동작하나? <a class="header-anchor" href="#_2-왜-현재는-global-memory로-동작하나" aria-label="Permalink to &quot;2. 왜 현재는 Global Memory로 동작하나?&quot;">​</a></h3><p>현재 Memory는 대부분 <strong>Global</strong> (모든 프로젝트에서 공유)로 동작합니다.<br> 이는 구현의 복잡도와 사용 편의성을 고려한 초기 설계로 보입니다.</p><p>현재는 “여러 프로젝트에서 공통으로 기억해야 할 정보”를 저장하는 데 최적화되어 있으며, 프로젝트별로 Memory를 격리하는 기능은 아직 제공되지 않습니다.</p><h3 id="_3-왜-agents-md-skill-memory를-구분해서-쓰나" tabindex="-1">3. 왜 AGENTS.md, Skill, Memory를 구분해서 쓰나? <a class="header-anchor" href="#_3-왜-agents-md-skill-memory를-구분해서-쓰나" aria-label="Permalink to &quot;3. 왜 AGENTS.md, Skill, Memory를 구분해서 쓰나?&quot;">​</a></h3><ul><li><strong>AGENTS.md</strong>: 프로젝트의 <strong>영구적인 큰 방향</strong>과 철학</li><li><strong>Skill</strong>: 특정 <strong>작업의 절차</strong>와 패턴</li><li><strong>Memory</strong>: 프로젝트를 하면서 <strong>발견한 사실</strong>이나 경험을 축적</li></ul><p>이 세 가지는 목적과 지속 기간이 다르기 때문에, 섞어서 사용하면 오히려 혼란스러워질 수 있습니다.</p><hr><h2 id="디버깅-체크리스트" tabindex="-1">디버깅 체크리스트 <a class="header-anchor" href="#디버깅-체크리스트" aria-label="Permalink to &quot;디버깅 체크리스트&quot;">​</a></h2><p>Memory가 제대로 동작하지 않을 때, 아래 순서대로 확인해보세요.</p><h3 id="memory가-저장되지-않을-때" tabindex="-1">Memory가 저장되지 않을 때 <a class="header-anchor" href="#memory가-저장되지-않을-때" aria-label="Permalink to &quot;Memory가 저장되지 않을 때&quot;">​</a></h3><ol><li><p><strong>Memory가 활성화되어 있는지 확인</strong></p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">memory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>또는 환경 변수 <code>GROK_MEMORY=1</code>이 설정되어 있는지 확인하세요.</p></li><li><p><strong>중요한 정보를 명확하게 전달했는지 확인</strong></p><ul><li>Memory는 자동으로 중요한 정보만 저장하려고 합니다.</li><li>너무 모호하게 말하면 (“적절히 해”, “좋은 코드로 만들어”) 저장되지 않을 수 있습니다.</li><li>구체적으로 말하는 것이 중요합니다.</li></ul></li></ol><h3 id="memory가-자동으로-불러와지지-않을-때" tabindex="-1">Memory가 자동으로 불러와지지 않을 때 <a class="header-anchor" href="#memory가-자동으로-불러와지지-않을-때" aria-label="Permalink to &quot;Memory가 자동으로 불러와지지 않을 때&quot;">​</a></h3><ol><li><p><strong>키워드가 너무 구체적이거나 모호한지 확인</strong></p><ul><li>Memory 검색은 키워드 기반입니다.</li><li>너무 긴 문장보다는 핵심 키워드(“JWT”, “Zustand”, “인증 로직”)를 사용하는 것이 더 잘 작동합니다.</li></ul></li><li><p><strong>Memory가 너무 많이 쌓여서 검색 효율이 떨어졌을 수 있음</strong></p><ul><li><code>/memory list</code>로 불필요한 Memory가 많이 쌓여있지 않은지 확인하세요.</li><li>주기적으로 정리하는 것이 좋습니다.</li></ul></li></ol><h3 id="memory가-이상한-내용을-불러올-때" tabindex="-1">Memory가 이상한 내용을 불러올 때 <a class="header-anchor" href="#memory가-이상한-내용을-불러올-때" aria-label="Permalink to &quot;Memory가 이상한 내용을 불러올 때&quot;">​</a></h3><ol><li><p><strong>오래된 정보가 남아있을 수 있음</strong></p><ul><li>프로젝트 구조가 바뀌었는데, 이전에 저장된 Memory가 그대로 남아있을 수 있습니다.</li><li><code>/memory list</code>로 확인하고 필요하면 삭제하세요.</li></ul></li><li><p><strong>비슷한 내용이 여러 개 저장되어 있을 수 있음</strong></p><ul><li>비슷한 내용이 중복 저장되면 Grok이 어떤 것을 우선할지 헷갈릴 수 있습니다.</li><li>중복되는 Memory는 정리하는 것이 좋습니다.</li></ul></li></ol><hr><p>이 두 섹션은 Memory를 더 깊이 이해하고, 문제가 생겼을 때 스스로 해결할 수 있도록 돕기 위해 추가되었습니다.</p><h2 id="전체-가이드-마무리" tabindex="-1">전체 가이드 마무리 <a class="header-anchor" href="#전체-가이드-마무리" aria-label="Permalink to &quot;전체 가이드 마무리&quot;">​</a></h2><p><code>12-메모리.md</code>를 모두 읽었다면, 이제 Grok Build의 <strong>장기 기억</strong> 기능을 이해한 것입니다.</p><h3 id="핵심-요약" tabindex="-1">핵심 요약 <a class="header-anchor" href="#핵심-요약" aria-label="Permalink to &quot;핵심 요약&quot;">​</a></h3><ul><li>Memory는 <strong>여러 세션에 걸쳐</strong> 중요한 정보를 기억하게 해주는 기능입니다.</li><li>활성화 방법은 CLI, 환경변수, config.toml이 있습니다.</li><li><code>/memory</code> 명령어로 직접 관리할 수 있습니다.</li><li>AGENTS.md, Skill과 함께 사용하면 훨씬 강력해집니다.</li><li>보안이 중요한 프로젝트에서는 신중하게 사용해야 합니다.</li></ul><h3 id="memory를-언제부터-도입하면-좋을까" tabindex="-1">Memory를 언제부터 도입하면 좋을까? <a class="header-anchor" href="#memory를-언제부터-도입하면-좋을까" aria-label="Permalink to &quot;Memory를 언제부터 도입하면 좋을까?&quot;">​</a></h3><ul><li>프로젝트가 어느 정도 진행되어서 <strong>반복되는 패턴</strong>이 보이기 시작할 때</li><li><strong>중요한 결정</strong>을 여러 번 설명하게 될 때</li><li>팀원들이 늘어나서 <strong>같은 설명을 반복</strong>하게 될 때</li></ul><p>초기에는 Memory 없이 시작했다가, 필요성을 느낄 때 활성화하는 것이 가장 자연스럽습니다.</p><hr><p><strong>12-메모리.md 끝</strong></p><p>여기까지 Grok Build의 Memory 기능을 전반적으로 정리했습니다.</p><p>Memory는 “한 번 알려주면 계속 기억해주는” 가장 편리한 기능 중 하나지만, 아직 실험적 단계라는 점을 잊지 마세요.</p><p>이제 Grok Build의 주요 확장 기능들을 모두 살펴보았습니다.</p><ul><li>Skills</li><li>MCP Servers</li><li>Plugins &amp; Marketplace</li><li>Hooks</li><li>Memory</li><li>Project Rules (AGENTS.md)</li></ul><p>이 기능들을 상황에 맞게 잘 조합하면, Grok Build를 단순한 코딩 도구가 아닌 <strong>프로젝트 전용 AI 개발 파트너</strong>로 만들 수 있습니다.</p><p>필요한 부분부터 하나씩 도입하면서, 자신만의 개발 환경을 만들어가시길 응원합니다.</p><p>이 문서에서 다루지 않은 더 구체적인 사례나, Memory 사용 중에 생긴 궁금증이 있으면 언제든 말씀해주세요.</p><hr><p><em>이 가이드는 실무에서 Memory를 도입하고 운영했던 경험을 바탕으로 작성되었습니다.</em></p><hr><ul><li>Memory 활성화 시 Grok의 동작 변화</li><li>Memory 사용 시 주의할 점과 한계</li><li>Memory 관련 Best Practices</li><li>전체 가이드 마무리</li></ul><hr><ul><li>Memory 관리 명령어 (<code>/memory list</code>, <code>/memory search</code>, <code>/memory delete</code> 등)</li><li>Memory 저장 전략 (무엇을 저장하면 좋은가)</li><li>Memory와 AGENTS.md, Skill의 함께 쓰는 방법</li><li>Privacy와 보안 고려사항</li></ul><hr>',207)])])}const y=a(l,[["render",s]]);export{c as __pageData,y as default};
